  <Variable name="hz.font.text" description="Tipografía de texto" type="font" default="normal 400 16px 'Schibsted Grotesk', 'Schibsted Grotesk Fallback', system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif" value="normal 400 16px 'Schibsted Grotesk', 'Schibsted Grotesk Fallback', system-ui, -apple-system, 'Segoe UI', Roboto, Arial, sans-serif"/>
