:root {
  color-scheme: light;
  --color-bg: $(hz.color.bg);
  --color-surface: $(hz.color.surface);
  --color-surface-2: $(hz.color.surface.alt);
  --color-ink: $(hz.color.ink);
  --color-ink-soft: $(hz.color.ink.soft);
  --color-muted: $(hz.color.muted);
  --color-rule: $(hz.color.rule);
  --color-horizon: $(hz.color.horizon);
  --color-accent: $(hz.color.accent);
  --color-accent-ink: $(hz.color.accent.ink);
  --color-sun: $(hz.color.sun);
  --color-sun-ink: $(hz.color.sun.ink);
  --color-live: $(hz.color.live);
  --color-focus: $(hz.color.focus);
  --color-footer: $(hz.color.footer);
  --color-footer-ink: $(hz.color.footer.ink);
  --sec-actualidad: $(hz.sec.actualidad);
  --sec-economia: $(hz.sec.economia);
  --sec-cultura: $(hz.sec.cultura);
  --sec-tecnologia: $(hz.sec.tecnologia);
  --sec-deportes: $(hz.sec.deportes);
  --sec-opinion: $(hz.sec.opinion);
  --font-title: $(hz.font.title);
  --font-text: $(hz.font.text);
  --step--2: clamp(0.7027rem, 0.7516rem + -0.0612vw, 0.7378rem);
  --step--1: clamp(0.8854rem, 0.8744rem + 0.0488vw, 0.9135rem);
  --step-0: clamp(1.0625rem, 1.0136rem + 0.2174vw, 1.1875rem);
  --step-1: clamp(1.275rem, 1.1698rem + 0.4674vw, 1.5438rem);
  --step-2: clamp(1.53rem, 1.3434rem + 0.8293vw, 2.0069rem);
  --step-3: clamp(1.836rem, 1.5335rem + 1.3442vw, 2.6089rem);
  --step-4: clamp(2.2032rem, 1.7382rem + 2.0668vw, 3.3916rem);
  --step-5: clamp(2.6438rem, 1.9531rem + 3.07vw, 4.4091rem);
  --step-6: clamp(3.1726rem, 2.1712rem + 4.4508vw, 5.7318rem);
  --space-3xs: clamp(0.2656rem, 0.2534rem + 0.0543vw, 0.2969rem);
  --space-2xs: clamp(0.5313rem, 0.5068rem + 0.1087vw, 0.5938rem);
  --space-xs: clamp(0.7969rem, 0.7602rem + 0.163vw, 0.8906rem);
  --space-s: clamp(1.0625rem, 1.0136rem + 0.2174vw, 1.1875rem);
  --space-m: clamp(1.5938rem, 1.5204rem + 0.3261vw, 1.7813rem);
  --space-l: clamp(2.125rem, 2.0272rem + 0.4348vw, 2.375rem);
  --space-xl: clamp(3.1875rem, 3.0408rem + 0.6522vw, 3.5625rem);
  --space-2xl: clamp(4.25rem, 4.0543rem + 0.8696vw, 4.75rem);
  --space-3xl: clamp(6.375rem, 6.0815rem + 1.3043vw, 7.125rem);
  --container: 84rem;
  --measure: 68ch;
  --gutter: clamp(1rem, 0.6rem + 1.8vw, 2rem);
  --radius-s: 4px;
  --radius-m: 10px;
  --radius-pill: 999px;
  --header-h: 3.5rem;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --dur-1: 140ms;
  --dur-2: 260ms;
  --dur-3: 520ms;
  --dur-4: 1100ms;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --color-bg: $(hz.dark.bg);
  --color-surface: $(hz.dark.surface);
  --color-surface-2: $(hz.dark.surface.alt);
  --color-ink: $(hz.dark.ink);
  --color-ink-soft: $(hz.dark.ink.soft);
  --color-muted: $(hz.dark.muted);
  --color-rule: $(hz.dark.rule);
  --color-horizon: $(hz.dark.horizon);
  --color-accent: $(hz.dark.accent);
  --color-accent-ink: $(hz.dark.accent.ink);
  --color-sun: $(hz.dark.sun);
  --color-sun-ink: $(hz.dark.sun.ink);
  --color-live: $(hz.dark.live);
  --color-focus: $(hz.dark.focus);
  --color-footer: $(hz.dark.footer);
  --color-footer-ink: $(hz.dark.footer.ink);
  --sec-actualidad: $(hz.sec.actualidad.dark);
  --sec-economia: $(hz.sec.economia.dark);
  --sec-cultura: $(hz.sec.cultura.dark);
  --sec-tecnologia: $(hz.sec.tecnologia.dark);
  --sec-deportes: $(hz.sec.deportes.dark);
  --sec-opinion: $(hz.sec.opinion.dark);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
    --color-bg: $(hz.dark.bg);
    --color-surface: $(hz.dark.surface);
    --color-surface-2: $(hz.dark.surface.alt);
    --color-ink: $(hz.dark.ink);
    --color-ink-soft: $(hz.dark.ink.soft);
    --color-muted: $(hz.dark.muted);
    --color-rule: $(hz.dark.rule);
    --color-horizon: $(hz.dark.horizon);
    --color-accent: $(hz.dark.accent);
    --color-accent-ink: $(hz.dark.accent.ink);
    --color-sun: $(hz.dark.sun);
    --color-sun-ink: $(hz.dark.sun.ink);
    --color-live: $(hz.dark.live);
    --color-focus: $(hz.dark.focus);
    --color-footer: $(hz.dark.footer);
    --color-footer-ink: $(hz.dark.footer.ink);
    --sec-actualidad: $(hz.sec.actualidad.dark);
    --sec-economia: $(hz.sec.economia.dark);
    --sec-cultura: $(hz.sec.cultura.dark);
    --sec-tecnologia: $(hz.sec.tecnologia.dark);
    --sec-deportes: $(hz.sec.deportes.dark);
    --sec-opinion: $(hz.sec.opinion.dark);
  }
}

head.b:template-skin:
body#layout { min-width: 0; max-width: 1100px; margin: 0 auto; padding: 24px; background: #F1F4F9; font: 14px/1.4 Arial, sans-serif; }
body#layout .c-skip, body#layout .c-nav__progress, body#layout .c-masthead__top, body#layout .c-nav__toggle,
body#layout .c-nav__mini, body#layout .c-nav__actions, body#layout .c-search, body#layout .c-nav-sentinel,
body#layout .c-nav__drawer-head, body#layout .c-scrim, body#layout .c-toast, body#layout .c-footer__bottom,
body#layout svg, body#layout template { display: none !important; }
body#layout .c-masthead, body#layout .c-nav, body#layout .c-ticker-section, body#layout .l-main, body#layout .c-footer { display: block; position: static; margin: 0 0 16px; padding: 0; background: none; transform: none; }
body#layout .l-container { max-width: none; padding: 0; }
body#layout .c-nav__menu { display: block; position: static; transform: none; }
body#layout .l-page { display: grid; grid-template-columns: minmax(0, 2fr) minmax(0, 1fr); gap: 16px; align-items: start; }
body#layout .l-main__blog, body#layout .l-home-extra { grid-column: 1; display: block; }
body#layout .l-sidebar { grid-column: 2; grid-row: 1 / span 2; }
body#layout .c-footer__grid { display: flex; flex-wrap: wrap; gap: 16px; }
body#layout .c-footer__grid > .section { flex: 1 1 200px; }
body#layout .section h4 { font-size: 13px; text-transform: uppercase; letter-spacing: .04em; color: #33405A; }
